from __future__ import absolute_import


from taf.selenium.gnb.oam.coam.cu.pages import v25R1
from taf.selenium.gnb.oam.coam.cu import pages
from taf.selenium.gnb.oam.coam.cu.pages.v25R1 import SnapshotPageViewPanelV25R1


class Diagnostic(v25R1.Diagnostic):
    def __init__(self, driver, version):
        super(Diagnostic, self).__init__(driver, version)
        self._instance_dict.update({"Snapshot": SnapshotPageV25R3(driver, version)})


class SnapshotPageV25R3(pages.SnapshotPage):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'Snapshot', 'Snapshot Collection']

    def __init__(self, driver, version):
        super(SnapshotPageV25R3, self).__init__(driver, version)
        self._view_panel = SnapshotPageViewPanelV25R3(driver, version)

    def collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        return self._view_panel.collect_snapshot(skip_session_renewal, renewal_password, snapshot_waiting_timeout)


class SnapshotPageViewPanelV25R3(SnapshotPageViewPanelV25R1):

    def __init__(self, driver, version):
        self.driver = driver
        super(SnapshotPageViewPanelV25R3, self).__init__(driver, version)

    def _handle_session_renewal_pop_up(self, skip_session_renewal, renewal_password, timeout=5):
        """
        Handles the session renewal pop-up based on the provided arguments.

        :param skip_session_renewal: bool, whether to skip session renewal
        :param renewal_password: str, password for session renewal
        :param timeout: int, timeout for the element to be available
        """
        if self.element_exists(self.locator.SNAPSHOT_DIALOG, timeout):
            if skip_session_renewal:
                self.click_enabled_element(self.locator.CONTINUE_WITH_OUT_RENEWAL_CHECKBOX)
            else:
                self.insert_text_to_enable_element(self.locator.SNAPSHOT_RENEWAL_PASSWORD_INPUT, renewal_password)
                self.click_enabled_element(self.locator.SNAPSHOT_POP_UP_COLLECT)
